import { IngestPipeline } from "@514labs/moose-lib";

// Event data model
export interface Event {
  event_id: string;
  event_ts: Date;
  user_id: string;
  event_type: string;
  value: number;
}

// Create ingestion pipeline for events
export const EventPipeline = new IngestPipeline<Event>("Event", {
  table: {
    orderByFields: ["event_ts", "user_id"] // Order by timestamp first, then user for better query performance
  },
  stream: true,
  ingestApi: true,
});

